const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses build-graph source text into a graph description:
 * `{ tasks: Map<name, cost>, deps: Map<name, string[]> }`, where `deps`
 * holds each task's dependency names in first-seen order, deduplicated.
 *
 * Throws `ParseError` for any malformed directive, and for the first name
 * (in input order) that a `dep` line uses but no `task` line declares.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const referencedNames = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new ParseError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new ParseError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new ParseError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new ParseError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
      if (!deps.has(name)) deps.set(name, [])
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new ParseError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const subject = words[1]
      const dependencies = words.slice(2)
      for (const name of [subject, ...dependencies]) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`line ${lineNo}: invalid task name ${name}`)
        }
      }
      referencedNames.push(subject, ...dependencies)
      const list = deps.get(subject) ?? []
      for (const dependency of dependencies) {
        if (!list.includes(dependency)) list.push(dependency)
      }
      deps.set(subject, list)
    } else {
      throw new ParseError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of referencedNames) {
    if (!tasks.has(name)) {
      throw new ParseError(`unknown task ${name}`, true)
    }
  }

  return { tasks, deps }
}
