/**
 * Finds the first cycle a depth-first search meets when it starts from each
 * task in ascending name order and walks each task's dependencies in
 * ascending name order. Throws `CycleError` naming the cycle from the
 * re-entered task, through the search stack, back to that task. Returns
 * nothing when the graph is acyclic.
 */
export function detectCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map(names.map((name) => [name, 'white']))
  const stack = []

  function visit(name) {
    state.set(name, 'gray')
    stack.push(name)
    const dependencies = [...(deps.get(name) ?? [])].sort()
    for (const dependency of dependencies) {
      const status = state.get(dependency)
      if (status === 'gray') {
        const start = stack.indexOf(dependency)
        throw new CycleError([...stack.slice(start), dependency])
      }
      if (status === 'white') visit(dependency)
    }
    state.set(name, 'black')
    stack.pop()
  }

  for (const name of names) {
    if (state.get(name) === 'white') visit(name)
  }
}

/**
 * Computes, for every task, its start time, finish time and wave depth
 * under unlimited workers. A task's start is the greatest finish among its
 * dependencies (0 when it has none) and its finish is its start plus its
 * cost. Its depth is 0 with no dependencies, or one more than the deepest
 * dependency's depth otherwise. The graph must already be known acyclic.
 */
export function computeSchedule(tasks, deps) {
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const dependencies = deps.get(name) ?? []
    let start = 0
    let taskDepth = 0
    for (const dependency of dependencies) {
      compute(dependency)
      start = Math.max(start, finish.get(dependency))
      taskDepth = Math.max(taskDepth, depth.get(dependency) + 1)
    }
    finish.set(name, start + tasks.get(name))
    depth.set(name, taskDepth)
  }

  for (const name of tasks.keys()) compute(name)

  const start = new Map()
  for (const name of tasks.keys()) start.set(name, finish.get(name) - tasks.get(name))

  return { start, finish, depth }
}

/**
 * Computes each task's priority for `pack`: its own cost plus the priority
 * of whichever task depending on it (directly or transitively) has the
 * greatest priority, or just its own cost when nothing depends on it.
 */
export function computePriority(tasks, deps) {
  const dependents = new Map([...tasks.keys()].map((name) => [name, []]))
  for (const [name, dependencies] of deps) {
    for (const dependency of dependencies) {
      dependents.get(dependency).push(name)
    }
  }

  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let maxDownstream = 0
    for (const dependent of dependents.get(name)) {
      maxDownstream = Math.max(maxDownstream, compute(dependent))
    }
    const value = tasks.get(name) + maxDownstream
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the build graph on `workerCount` workers, greedily starting the
 * highest-priority ready task on the lowest-index free worker whenever both
 * are available, and otherwise advancing to the next time a worker frees.
 * Returns `{ workers, makespan }`, where `workers[i]` lists `{ name, start,
 * finish }` in the order worker `i` ran them.
 */
export function packWorkers(tasks, deps, workerCount) {
  const priority = computePriority(tasks, deps)
  const names = [...tasks.keys()].sort()

  const workers = Array.from({ length: workerCount }, () => [])
  const workerFreeAt = new Array(workerCount).fill(0)
  const finishTime = new Map()
  const started = new Set()

  let currentTime = 0
  let makespan = 0

  while (started.size < names.length) {
    let progressed = true
    while (progressed) {
      progressed = false

      const freeWorkers = []
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= currentTime) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      let ready = names.filter((name) => {
        if (started.has(name)) return false
        const dependencies = deps.get(name) ?? []
        return dependencies.every((dependency) => finishTime.get(dependency) <= currentTime)
      })
      if (ready.length === 0) break

      ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : a > b ? 1 : 0))
      const chosen = ready[0]
      const workerIndex = freeWorkers[0]

      const start = currentTime
      const finish = start + tasks.get(chosen)
      workers[workerIndex].push({ name: chosen, start, finish })
      workerFreeAt[workerIndex] = finish
      finishTime.set(chosen, finish)
      started.add(chosen)
      makespan = Math.max(makespan, finish)

      progressed = true
    }

    if (started.size >= names.length) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > currentTime) next = Math.min(next, workerFreeAt[i])
    }
    currentTime = next
  }

  return { workers, makespan }
}
