  if (mode === 'waves') {
    const { finish, depth } = computeSchedule(tasks, deps)
    const byDepth = []
    for (const name of names) {
      const d = depth.get(name)
      ;(byDepth[d] ??= []).push(name)
    }
    let output = ''
    for (let k = 0; k < byDepth.length; k++) {
      output += `wave ${k}: ${byDepth[k].join(' ')}\n`
    }
    const total = names.length === 0 ? 0 : Math.max(...names.map((name) => finish.get(name)))
    output += `total ${total}\n`
    process.stdout.write(output)
  } else if (mode === 'explain') {
    const { start, finish, depth } = computeSchedule(tasks, deps)
    let output = ''
    for (const name of names) {
      output += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    const total = names.length === 0 ? 0 : Math.max(...names.map((name) => finish.get(name)))
    output += `total ${total}\n`
    process.stdout.write(output)
  } else {
    const { workers, makespan } = packWorkers(tasks, deps, workerCount)
    let output = ''
    for (let i = 0; i < workers.length; i++) {
      const runs = workers[i].map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
      output += `worker ${i}:${runs}\n`
    }
    output += `makespan ${makespan}\n`
    process.stdout.write(output)
  }
}

main()
